import { existsSync, readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";
import { buildMathQuestions } from "./math";
import { QuestionSchema, SubjectSchema, type Question, type Subject } from "./questions";

export interface Bank {
  subjects: Subject[];
  questions: Question[];
}

export interface Problem {
  file: string;
  id?: string;
  message: string;
}

/** Subjects whose questions are (also) generated by code rather than written in bank/ files. */
const GENERATED: Record<string, () => Question[]> = { mathematics: () => buildMathQuestions() };

/**
 * Reads and checks the whole question bank. Every problem is reported with its file and question id,
 * in plain words, so a contributor can fix a pull request without reading the code.
 */
export function loadBank(root: string): { bank: Bank; problems: Problem[] } {
  const problems: Problem[] = [];
  const at = (file: string) => relative(process.cwd(), file).replace(/\\/g, "/");

  const subjectsFile = join(root, "subjects.json");
  const subjectsParsed = SubjectSchema.array().safeParse(readJson(subjectsFile, problems));
  if (!subjectsParsed.success) {
    for (const issue of subjectsParsed.error.issues) problems.push({ file: at(subjectsFile), message: describe(issue) });
    return { bank: { subjects: [], questions: [] }, problems };
  }
  const subjects = subjectsParsed.data;

  const questions: { q: Question; file: string }[] = [];
  for (const subject of subjects) {
    const dir = join(root, subject.id);
    const files = existsSync(dir) ? readdirSync(dir).filter((f) => f.endsWith(".json")).sort() : [];
    for (const name of files) {
      const file = join(dir, name);
      const data = readJson(file, problems);
      if (data === undefined) continue;
      if (!Array.isArray(data)) {
        problems.push({ file: at(file), message: "the file must contain a JSON array of questions: [ {...}, {...} ]" });
        continue;
      }
      data.forEach((item, i) => {
        const id = typeof item?.id === "string" ? item.id : `question #${i + 1}`;
        const parsed = QuestionSchema.safeParse(item);
        if (!parsed.success) {
          for (const issue of parsed.error.issues) problems.push({ file: at(file), id, message: describe(issue) });
          return;
        }
        const q = parsed.data;
        if (q.subject !== subject.id) problems.push({ file: at(file), id, message: `"subject" must be "${subject.id}" for questions in bank/${subject.id}/` });
        if (q.source === "template") problems.push({ file: at(file), id, message: `"source" must be "authored" for questions written in bank files` });
        questions.push({ q, file: at(file) });
      });
    }
    for (const q of GENERATED[subject.id]?.() ?? []) questions.push({ q, file: "src/lib/math.ts (generated)" });
  }

  const seenIds = new Map<string, string>();
  const seenQuestions = new Map<string, string>();
  const topicsBySubject = new Map(subjects.map((s) => [s.id, s.topics]));
  for (const { q, file } of questions) {
    const topics = topicsBySubject.get(q.subject) ?? [];
    if (!topics.includes(q.topic)) {
      problems.push({ file, id: q.id, message: `topic "${q.topic}" isn't listed for ${q.subject} in bank/subjects.json. Use one of: ${topics.join(", ")}` });
    }
    const earlier = seenIds.get(q.id);
    if (earlier) problems.push({ file, id: q.id, message: `the id "${q.id}" is already used in ${earlier}. Ids must be unique.` });
    seenIds.set(q.id, file);

    const key = `${q.stem}|${q.options.join("|")}`;
    const twin = seenQuestions.get(key);
    if (twin) problems.push({ file, id: q.id, message: `this question is a duplicate of ${twin}` });
    seenQuestions.set(key, q.id);

    if (new Set(q.options.map((o) => o.trim().toLowerCase())).size !== 4) {
      problems.push({ file, id: q.id, message: "the four options must all be different" });
    }
    const right = q.options[q.answer];
    if (!q.explanation.toLowerCase().includes(right.toLowerCase())) {
      problems.push({
        file,
        id: q.id,
        message: `the explanation must mention the correct option ("${right}"). If it doesn't, the "answer" index may point at the wrong option.`,
      });
    }
  }

  return { bank: { subjects, questions: questions.map(({ q }) => q) }, problems };
}

function readJson(file: string, problems: Problem[]): unknown {
  try {
    return JSON.parse(readFileSync(file, "utf8"));
  } catch (err) {
    problems.push({ file: file.replace(/\\/g, "/"), message: `isn't valid JSON: ${err instanceof Error ? err.message : err}` });
    return undefined;
  }
}

function describe(issue: { path: PropertyKey[]; message: string; code: string; keys?: string[] }): string {
  const where = issue.path.length > 0 ? `"${issue.path.map(String).join(".")}"` : "the question";
  if (issue.code === "unrecognized_keys") return `unknown field(s) ${issue.keys?.map((k) => `"${k}"`).join(", ")}. Check the spelling against CONTRIBUTING.md.`;
  return `${where}: ${issue.message}`;
}
